  plugins: [
    storybookTest({ storybookScript: 'npm run storybook --no-open' }),
  ],
  test: {
    browser: {
      enabled: true,
      name: 'chromium',
      provider: 'playwright',
    },
    setupFiles: ['./.storybook/vitest.setup.ts'],
